// ORDER TO SHIP ENGINE — CONFIG
// Everything you might want to change lives in this one node. Nothing else in either
// workflow needs editing.
//
// The same config node ships in BOTH workflows ("01 capture and confirm" and
// "02 progress and ship"). If you change it in one, paste it into the other — build.py
// regenerates both from this one file, so normally you never have to.
//
// A blank key or a false flag means that step is SKIPPED, never that the run fails.
// That is what lets this be demonstrated on a screen-share before a single credential
// exists.

// ---------------------------------------------------------------- The production board
// The Google Sheet the team already runs as their production board. The id is the long
// code in the sheet's web address:
// docs.google.com/spreadsheets/d/<THIS BIT>/edit
const BOARD_SHEET_ID = '';
const BOARD_TAB      = 'Orders';

// Set to true only when ALL of these are in place:
//   1. the sheet exists with the headings below (see sheet/Orders.csv)
//   2. BOARD_SHEET_ID above is filled in
//   3. the [cred] Sheets nodes in both workflows have Google credentials attached
// Until then the workflows run against a built-in demo board: rows are shown in
// STOP nodes instead of being written, and fabricated customers can never be emailed.
const BOARD_READY = false;

// The column headings, exactly as they appear in row 1 of the Orders tab.
// 'Items (json)' holds the line items as JSON so the board stays one row per order.
const COLUMNS = {
  order_key:         'Order key',
  source:            'Source',
  order_id:          'Order no.',
  placed:            'Placed',
  customer:          'Customer',
  email:             'Email',
  items:             'Items (json)',
  spec:              'Spec',
  window_start:      'Ship window start',
  window_end:        'Ship window end',
  stage:             'Stage',
  confirmation_sent: 'Confirmation sent',
  carrier:           'Carrier',
  tracking:          'Tracking no.',
  ship_date:         'Shipped date',
  ship_email_sent:   'Ship email sent',
  notes:             'Notes'
};

// The stages the team moves a row through. The workflow writes 'New order' when the row
// lands and 'Confirmed' once the confirmation email is away; the OFFICE moves rows to
// 'In production' and finally 'Shipped' (when a label exists). That last flip is what
// triggers the shipping email. Nothing ships before a confirmation was recorded.
const STAGE_ON_ARRIVAL = 'New order';
const STAGE_CONFIRMED  = 'Confirmed';
const STAGE_SHIPPED    = 'Shipped';
const STAGES = ['New order', 'Confirmed', 'In production', 'Shipped', 'Delivered',
  'On hold', 'Cancelled'];

// ---------------------------------------------------------------- The stores
// Which store webhooks feed this. Square is in DEPOSIT_SOURCES: for designer/custom
// goods the post says the workflow may begin when the deposit is received, so a Square
// order whose payment has not landed is held until it has. Shopify and Etsy orders only
// arrive here once the store marks them confirmed/paid, so they are not gated.
const SOURCE_LABELS = { shopify: 'Shopify', etsy: 'Etsy', square: 'Square' };
const DEPOSIT_SOURCES = ['square'];

// ---------------------------------------------------------------- Product rules
// The rules/formulas the client provides, in one table so every number an email quotes
// can be traced back to a rule. Each order line is looked up by sku.
//
//   lead_days  how many working days this piece takes to build. The confirmation email's
//              ship window = order date + the LONGEST lead in the order + the buffers
//              below. Nothing ships before its promise, so the window is the honest one.
//   anchors    the wall hardware the customer needs for installation:
//                { mode: 'none' }        free-standing piece — no wall anchors
//                { mode: 'fixed', qty }  per unit (e.g. a bracket kit = 8 anchors)
//                { mode: 'per_metre' }   qty per metre of the line's length, rounded up
//   manual     the installation manual URL for that product
const PRODUCT_RULES = [
  { sku: 'DIN-TBL-WALNUT-6', name: 'Walnut dining table, 6-seat', lead_days: 14,
    anchors: { mode: 'none' }, manual: '', note: 'Free-standing piece — no wall anchors.' },
  { sku: 'CON-OAK-160', name: 'Oak console, 160 cm', lead_days: 10,
    anchors: { mode: 'none' }, manual: '', note: 'Free-standing piece — no wall anchors.' },
  { sku: 'SHLF-OAK-120', name: 'Oak wall shelf, 120 cm', lead_days: 6,
    anchors: { mode: 'per_metre', qty: 2 }, manual: 'https://example.com/manuals/oak-shelf-120.pdf',
    note: 'Two brackets supplied; fixings sized for the wall type.' },
  { sku: 'BRK-STEEL-L', name: 'Steel L-bracket set (pair)', lead_days: 3,
    anchors: { mode: 'fixed', qty: 8 }, manual: '',
    note: 'Four anchors per bracket; use the template supplied.' }
];

// A line item whose sku is NOT in the table above cannot be given an honest ship window
// or an honest anchor count. true = hold the order and show it in a STOP node instead of
// promising something the rules cannot support. Add the missing sku to PRODUCT_RULES and
// re-run.
const HOLD_UNRULED_ITEMS = true;

// The shipping promise, in working days (Mon-Fri):
//   earliest = order date + longest lead in the order + START buffer
//   latest   = order date + longest lead in the order + END buffer
// The email quotes the window, never a single date.
const WINDOW_BUFFER_START_DAYS = 3;
const WINDOW_BUFFER_END_DAYS   = 8;

// ---------------------------------------------------------------- Sending
const COMPANY_NAME = 'Example Furniture Co';
const FROM_NAME    = 'Example Furniture Co';
const REPLY_TO     = '';          // where customer replies should land
const PHONE        = '';
const WEBSITE      = '';

// The personalised emails. The braces are filled in code from the order and the rules —
// the model is never asked to invent a date, an anchor count or a manual link.
const CONFIRM_SUBJECT = 'Your {company} order {order} — thank you';
const SHIP_SUBJECT    = 'Your {company} order {order} has shipped';

// ---------------------------------------------------------------- ShipStation
// Optional. When the office creates a label in ShipStation they flip the board row to
// 'Shipped'; this workflow then tries to pull carrier, tracking number and ship date
// from ShipStation instead of asking anyone to type them.
//
// Set true only when: the [cred] ShipStation node has credentials attached AND the
// fetch path has been checked against your ShipStation account (see README — the
// endpoint is the one integration point to confirm on a live account).
const SHIPSTATION_READY = false;
const SHIPSTATION_BASE  = 'https://api.shipstation.com';

// ---------------------------------------------------------------- Safety switch
//   TEST_RUN true,  TEST_EMAIL blank -> PREVIEW. Rows are written to the sheet (when
//                                      BOARD_READY) but no email is sent. Ships this way.
//   TEST_RUN true,  TEST_EMAIL set   -> TEST. Emails really send, but every one goes to
//                                      TEST_EMAIL instead of the customer.
//   TEST_RUN false                   -> LIVE. Customers get the real thing.
const TEST_RUN   = true;
const TEST_EMAIL = '';

// While the demo board is in use (no sheet configured) the run is FORCED into preview:
// a fabricated customer can never be emailed, whatever TEST_RUN says.
const DEMO_MODE = BOARD_READY !== true;

let MODE = TEST_RUN !== true ? 'live'
  : (TEST_EMAIL.trim() !== '' ? 'test' : 'preview');
if (DEMO_MODE && MODE !== 'preview') MODE = 'preview';

// ---------------------------------------------------------------- Demo board
// The rows the workflows run against until BOARD_READY is set. Every customer, order and
// product here is fabricated. The mix is deliberate — it has to be able to show every
// gate doing its job:
//   * a 'Shipped' row that was confirmed and has tracking pasted   -> shipping email
//   * a 'Shipped' row with NO tracking and no ShipStation          -> STOP: tracking missing
//   * a 'Shipped' row that was never confirmed                     -> STOP: never shipped unconfirmed
//   * a finished row already emailed                               -> left alone (idempotent)
//   * open rows in production / new                                -> left alone
const DEMO_ORDERS = [
  {
    order_key: 'shopify|5102', source: 'shopify', order_id: '5102', placed: '2026-09-02 09:41',
    customer: 'Dana Whitfield', email: 'user@example.com',
    items: '[{"sku":"DIN-TBL-WALNUT-6","name":"Walnut dining table, 6-seat","qty":1,"dim_m":"","spec":"2200 x 1000 x 750 mm, matte oil finish"},{"sku":"BRK-STEEL-L","name":"Steel L-bracket set (pair)","qty":2,"dim_m":"","spec":""}]',
    spec: '', window_start: '2026-09-23', window_end: '2026-09-30', stage: 'In production',
    confirmation_sent: '2026-09-02 09:41', carrier: '', tracking: '', ship_date: '',
    ship_email_sent: '', notes: ''
  },
  {
    order_key: 'etsy|2218', source: 'etsy', order_id: '2218', placed: '2026-09-04 14:02',
    customer: 'Marlon Reyes', email: 'user@example.com',
    items: '[{"sku":"SHLF-OAK-120","name":"Oak wall shelf, 120 cm","qty":1,"dim_m":"1.2","spec":"120 x 22 x 4 cm"},{"sku":"BRK-STEEL-L","name":"Steel L-bracket set (pair)","qty":1,"dim_m":"","spec":""}]',
    spec: '', window_start: '2026-09-18', window_end: '2026-09-25', stage: 'Shipped',
    confirmation_sent: '2026-09-04 14:02', carrier: 'UPS', tracking: '1Z999AA10123456784',
    ship_date: '2026-09-16', ship_email_sent: '', notes: ''
  },
  {
    order_key: 'shopify|5117', source: 'shopify', order_id: '5117', placed: '2026-09-05 16:30',
    customer: 'Priya Nair', email: 'user@example.com',
    items: '[{"sku":"CON-OAK-160","name":"Oak console, 160 cm","qty":1,"dim_m":"","spec":"160 x 40 x 75 cm, no back panel"}]',
    spec: '', window_start: '2026-09-22', window_end: '2026-09-29', stage: 'Shipped',
    confirmation_sent: '2026-09-05 16:30', carrier: '', tracking: '', ship_date: '',
    ship_email_sent: '', notes: ''
  },
  {
    order_key: 'square|ORD-9081', source: 'square', order_id: 'ORD-9081', placed: '2026-09-08 11:12',
    customer: 'Tom Okafor', email: 'user@example.com',
    items: '[{"sku":"DIN-TBL-WALNUT-6","name":"Walnut dining table, 6-seat","qty":1,"dim_m":"","spec":"custom width 2400 mm"}]',
    spec: 'Custom width 2400 mm', window_start: '2026-09-28', window_end: '2026-10-05',
    stage: 'Shipped', confirmation_sent: '', carrier: '', tracking: '', ship_date: '',
    ship_email_sent: '', notes: ''
  },
  {
    order_key: 'shopify|5123', source: 'shopify', order_id: '5123', placed: '2026-09-09 08:05',
    customer: 'Elena Rossi', email: 'user@example.com',
    items: '[{"sku":"SHLF-OAK-120","name":"Oak wall shelf, 120 cm","qty":2,"dim_m":"1.2","spec":""}]',
    spec: '', window_start: '2026-09-22', window_end: '2026-09-29', stage: 'New order',
    confirmation_sent: '', carrier: '', tracking: '', ship_date: '', ship_email_sent: '',
    notes: ''
  },
  {
    order_key: 'etsy|2190', source: 'etsy', order_id: '2190', placed: '2026-08-28 10:15',
    customer: 'June Park', email: 'user@example.com',
    items: '[{"sku":"CON-OAK-160","name":"Oak console, 160 cm","qty":1,"dim_m":"","spec":""}]',
    spec: '', window_start: '2026-09-14', window_end: '2026-09-21', stage: 'Delivered',
    confirmation_sent: '2026-08-28 10:15', carrier: 'FedEx', tracking: '778899001122',
    ship_date: '2026-09-15', ship_email_sent: '2026-09-15 09:30', notes: ''
  }
];

return [{
  json: {
    company_name: COMPANY_NAME,
    from_name:    FROM_NAME,
    reply_to:     REPLY_TO.trim(),
    phone:        PHONE.trim(),
    website:      WEBSITE.trim(),

    board_sheet_id: BOARD_SHEET_ID.trim(),
    board_tab:      BOARD_TAB,
    columns:        COLUMNS,
    board_ready:    BOARD_READY === true,

    source_labels:  SOURCE_LABELS,
    deposit_sources: DEPOSIT_SOURCES,

    product_rules:    PRODUCT_RULES,
    hold_unruly:      HOLD_UNRULED_ITEMS === true,
    window_start_days: Number(WINDOW_BUFFER_START_DAYS) || 0,
    window_end_days:   Number(WINDOW_BUFFER_END_DAYS) || 0,

    stage_on_arrival: STAGE_ON_ARRIVAL,
    stage_confirmed:  STAGE_CONFIRMED,
    stage_shipped:    STAGE_SHIPPED,
    stages:           STAGES,

    confirm_subject: CONFIRM_SUBJECT,
    ship_subject:    SHIP_SUBJECT,

    shipstation_ready: SHIPSTATION_READY === true,
    shipstation_base:  SHIPSTATION_BASE,

    demo_orders: DEMO_ORDERS,
    demo_mode:   DEMO_MODE,

    // derived flags — the gates read these, never the raw constants
    mode:          MODE,
    preview_only:  MODE === 'preview',
    test_send:     MODE === 'test',
    live_send:     MODE === 'live',
    send_enabled:  MODE !== 'preview',
    test_email:    TEST_EMAIL.trim()
  }
}];

// Turns whatever the store posted into ONE common order object, whatever the store is.
// Shopify, Etsy and Square all name their fields differently, so the parser detects the
// source and digs the same facts out of each shape. An unknown shape is rejected with a
// reason, never half-read.
//
// Output: one item carrying `order` (the common shape) and `_ok` / `_problems`.
const CFG = () => $('config').first().json;

function esc(v) {
  return String(v == null ? '' : v).replace(/[<>&"]/g, function (c) {
    return { '<': '&lt;', '>': '&gt;', '&': '&amp;', '"': '&quot;' }[c];
  });
}
function text(v) {
  return String(v == null ? '' : v).trim();
}

function cleanLines(lines, get) {
  const out = [];
  for (const li of (lines || [])) {
    const g = get(li);
    if (!g) continue;
    const qty = Math.max(1, Math.round(Number(g.qty) || 1));
    out.push({ sku: text(g.sku), name: text(g.name), qty: qty,
               dim_m: text(g.dim_m), spec: text(g.spec) });
  }
  return out;
}

function parse(raw, cfg) {
  const problems = [];
  const src = detect(raw);
  if (!src) {
    problems.push('did not match a Shopify, Etsy or Square order shape');
    return { _ok: false, _problems: problems, order: null };
  }

  let order = null;
  if (src === 'shopify') order = shopifyOrder(raw, cfg);
  if (src === 'etsy')    order = etsyOrder(raw, cfg);
  if (src === 'square')  order = squareOrder(raw, cfg);
  if (!order) {
    problems.push('could not read the order fields from the payload');
    return { _ok: false, _problems: problems, order: null };
  }

  // The rules for what a usable order is, in one place.
  if (!order.email || order.email.indexOf('@') < 0) problems.push('no usable customer email');
  if (!order.order_id) problems.push('no order number');
  if (!order.line_items || order.line_items.length === 0) problems.push('no line items');
  for (const li of order.line_items || []) {
    if (!li.sku) problems.push('a line item has no sku (map it in PRODUCT_RULES)');
  }
  const deposits = cfg.deposit_sources || [];
  if (deposits.indexOf(order.source) >= 0 && order.deposit_paid !== true) {
    problems.push('deposit not yet received (Square custom order waits for it)');
  }

  order.source_label = (cfg.source_labels || {})[order.source] || order.source;
  return { _ok: problems.length === 0, _problems: problems, order: order };
}

function detect(raw) {
  if (!raw || typeof raw !== 'object') return '';
  if (raw.line_items && (raw.email || (raw.customer && raw.customer.email))) return 'shopify';
  if (raw.receipt && raw.receipt.transactions) return 'etsy';
  if (raw.transactions && raw.buyer_email) return 'etsy';
  if (raw.payment || (raw.data && raw.data.object && raw.data.object.payment)) return 'square';
  if (raw.data && raw.data.object && raw.data.object.order) return 'square';
  if (raw.fulfillments || raw.tenders || raw.location_id) return 'square';
  return '';
}

function shopifyOrder(r, cfg) {
  const c = (r.customer || {});
  const name = text(c.first_name || c.name) + (text(c.last_name) ? ' ' + text(c.last_name) : '');
  return {
    source: 'shopify',
    order_id: text(r.id || r.name),
    placed: (text(r.created_at) || '').slice(0, 16).replace('T', ' '),
    customer_name: name || 'Shopify customer',
    email: text(r.email || c.email),
    line_items: cleanLines(r.line_items, (li) => ({
      sku: li.sku || li.variant_sku || li.product_id,
      name: li.title || li.name, qty: li.quantity, dim_m: '', spec: ''
    })),
    spec_summary: text(r.note),
    deposit_paid: true,
    raw_order_id: r.id
  };
}

function etsyOrder(r, cfg) {
  const receipt = r.receipt || {};
  const tx = receipt.transactions || r.transactions || [];
  const placed = Number(receipt.create_timestamp || r.create_timestamp);
  return {
    source: 'etsy',
    order_id: text(receipt.receipt_id || r.receipt_id),
    placed: placed ? new Date(placed * 1000).toISOString().slice(0, 16).replace('T', ' ')
                   : '',
    customer_name: text(receipt.name || r.name || 'Etsy customer'),
    email: text(receipt.buyer_email || r.buyer_email),
    line_items: cleanLines(tx, (li) => {
      const pd = (li.product_data && typeof li.product_data === 'object') ? li.product_data : {};
      return { sku: pd.sku || li.sku || li.product_id || li.listing_id,
               name: li.title || li.name, qty: li.quantity, dim_m: '', spec: '' };
    }),
    spec_summary: '',
    deposit_paid: true,
    raw_order_id: receipt.receipt_id
  };
}

function squareOrder(r, cfg) {
  // A Square 'payment.updated' webhook carries the payment; an 'order.created' webhook
  // (before the deposit lands) carries only the order. Both must read as square — the
  // deposit gate then holds the order.created one until the payment arrives.
  const pay = (r.payment) || (r.data && r.data.object && r.data.object.payment) || {};
  const ord = (r.data && r.data.object && r.data.object.order) || r.order || {};
  const items = ((pay.line_items && pay.line_items.length) ? pay.line_items
                                                          : (ord.line_items || []));
  const hasPay = Object.keys(pay).length > 0;
  return {
    source: 'square',
    order_id: text(pay.order_id || ord.id),
    placed: (text(pay.created_at || ord.created_at || '')).slice(0, 16).replace('T', ' '),
    customer_name: text(pay.buyer_name || ord.customer_name || 'Square customer'),
    email: text(pay.receipt_email || pay.buyer_email_address || ord.buyer_email_address),
    line_items: cleanLines(items, (li) => ({
      sku: li.sku || li.catalog_object_id || li.uid,
      name: li.name, qty: li.quantity, dim_m: '', spec: ''
    })),
    spec_summary: text(pay.note || ord.note || ''),
    deposit_paid: hasPay && ['COMPLETED', 'APPROVED', 'CAPTURED']
      .indexOf(text(pay.status).toUpperCase()) >= 0,
    raw_order_id: pay.id || ord.id
  };
}

// What n8n hands the Code node depends on how the webhook received the POST: sometimes
// the parsed body sits at the top of $json, sometimes under 'body', and occasionally as
// a JSON *string*. Try every candidate until one reads as an order, so the store's
// webhook is not at the mercy of n8n's wrapping. If nothing reads, the reason says which
// keys were actually seen — that is the debugging breadcrumb.
function toObject(x) {
  if (!x) return null;
  if (typeof x === 'string') {
    try { return JSON.parse(x); } catch (e) { return null; }
  }
  return (typeof x === 'object') ? x : null;
}

const cfg = CFG();
const incoming = toObject($input.first().json) || {};
const candidates = [incoming];
const body = toObject(incoming.body);
if (body) {
  candidates.push(body);
  const inner = toObject(body.body);
  if (inner) candidates.push(inner);
}

let parsed = null;
for (const c of candidates) {
  const p = parse(c, cfg);
  if (p.order && p.order.source) { parsed = p; break; }
  parsed = parsed || p;
}
if (!parsed) parsed = parse({}, cfg);

const order = parsed.order || {};
const seenKeys = Object.keys(incoming).join(',');
return [{
  json: Object.assign({
    order:     order,
    order_key: order.source ? (order.source + '|' + order.order_id) : '',
    _ok:       parsed._ok,
    _problems: parsed._problems.concat(
      order.source ? [] : ['webhook body keys seen: ' + (seenKeys || '(empty)')])
  }, order ? { _email: esc(order.email || '') } : {})
}];

// Not a usable order. Dropped here rather than reaching the board, with the reasons kept
// so the execution list says why. An awaiting-deposit Square order lands here too — it is
// not lost, it just waits until Square posts the payment webhook.
return $input.all().map((i) => ({
  json: Object.assign({}, i.json, {
    _outcome: 'rejected',
    _reason: (i.json._problems || []).join('; ') || 'did not read as an order'
  })
}));

// No sheet configured yet: emit the built-in demo board rows instead. Rows come out keyed
// by the same HEADINGS a Google Sheets read would produce, so everything downstream is
// identical whether the data is real or fabricated. Every customer here is invented.
const cfg = $('config').first().json;
const cols = cfg.columns || {};
const rows = (cfg.demo_orders || []).map(function (o) {
  const row = {};
  for (const k of Object.keys(cols)) row[cols[k]] = (o[k] != null ? String(o[k]) : '');
  row._demo = true;
  return row;
});
return rows.map((r) => ({ json: r }));

// Dedupe: has this store order already landed on the board? The board rows come in as
// items (from the sheet or the demo board — same shape either way) and are folded into
// one answer. Order keys are 'source|order-no', so the same number on a different store
// is a different order and is never mistaken for one.
const incoming = $('read the order').first().json;
const key = incoming.order_key;
const rows = $input.all().map((i) => i.json);
const found = rows.filter((r) => r['Order key'] === key)[0] || null;
return [{
  json: Object.assign({}, incoming, {
    _known: !!found,
    known_row: found,
    board_rows_read: rows.length
  })
}];

// The store redelivered an order we already hold (webhooks retry; Shopify and Etsy both
// do). The row already exists, so nothing is written twice — "never typed twice". The
// store still gets a friendly ok so its webhook stops retrying.
return $input.all().map((i) => ({
  json: Object.assign({}, i.json, {
    _outcome: 'duplicate',
    _reason: 'order ' + i.json.order_key + ' is already on the board'
  })
}));

// Plans the build for one new order: checks every line item against PRODUCT_RULES,
// works out the shipping window (working days only — never a promise on a weekend), and
// builds the board row. A sku with no rule is a GAP, not a guess: the email must not
// promise a date the rules cannot support.
function parseDate(s) {
  // '2026-09-02 09:41' or an ISO string.
  const t = String(s || '').trim();
  if (!t) return null;
  const d = new Date(t.indexOf('T') >= 0 ? t : t.replace(' ', 'T'));
  return isNaN(d.getTime()) ? null : d;
}
function addWorkdays(d, n) {
  let x = new Date(d.getTime());
  let left = n;
  while (left > 0) {
    x.setDate(x.getDate() + 1);
    const dow = x.getDay();
    if (dow !== 0 && dow !== 6) left--;
  }
  return x;
}
function fmt(d) {
  const p = (n) => (n < 10 ? '0' : '') + n;
  return d.getFullYear() + '-' + p(d.getMonth() + 1) + '-' + p(d.getDate());
}
function esc(v) {
  return String(v == null ? '' : v).replace(/[<>&"]/g, function (c) {
    return { '<': '&lt;', '>': '&gt;', '&': '&amp;', '"': '&quot;' }[c];
  });
}

const cfg = $('config').first().json;
const incoming = $input.first().json;
const order = incoming.order || {};
const rules = (cfg.product_rules || []).reduce(function (m, r) {
  m[String(r.sku).trim().toLowerCase()] = r;
  return m;
}, {});

const gaps = [];
const linePlan = (order.line_items || []).map(function (li) {
  const rule = rules[String(li.sku).trim().toLowerCase()];
  const base = { sku: li.sku, name: li.name || li.sku, qty: li.qty || 1,
                 dim_m: li.dim_m || '' };
  if (!rule) {
    gaps.push(li.sku || li.name || 'an unnamed item');
    return Object.assign(base, { lead_days: 0, known: false });
  }
  return Object.assign(base, {
    lead_days: Number(rule.lead_days) || 0,
    anchors: rule.anchors || { mode: 'none' },
    manual: rule.manual || '',
    note: rule.note || '',
    known: true
  });
});

let windowStart = null, windowEnd = null, maxLead = 0;
const placed = parseDate(order.placed) || new Date();
if (gaps.length === 0) {
  maxLead = linePlan.reduce(function (m, lp) { return Math.max(m, lp.lead_days); }, 0);
  const b0 = Number(cfg.window_start_days) || 0;
  const b1 = Number(cfg.window_end_days) || 0;
  windowStart = addWorkdays(placed, maxLead + b0);
  windowEnd = addWorkdays(placed, maxLead + Math.max(b1, b0));
}

const cols = cfg.columns || {};
const h = (k) => cols[k] || k;
const itemsJson = JSON.stringify((order.line_items || []).map(function (li) {
  return { sku: li.sku, name: li.name, qty: li.qty, dim_m: li.dim_m, spec: li.spec };
}));

const row = {};
const placedTime = String(order.placed || '').slice(11, 16);
row[h('order_key')] = incoming.order_key;
row[h('source')] = order.source_label || order.source || '';
row[h('order_id')] = order.order_id || '';
row[h('placed')] = fmt(placed) + (placedTime ? ' ' + placedTime : '');
row[h('customer')] = order.customer_name || '';
row[h('email')] = order.email || '';
row[h('items')] = itemsJson;
row[h('spec')] = order.spec_summary || '';
row[h('window_start')] = windowStart ? fmt(windowStart) : '';
row[h('window_end')] = windowEnd ? fmt(windowEnd) : '';
row[h('stage')] = cfg.stage_on_arrival || 'New order';
row[h('confirmation_sent')] = '';
row[h('carrier')] = '';
row[h('tracking')] = '';
row[h('ship_date')] = '';
row[h('ship_email_sent')] = '';
row[h('notes')] = '';

return [{
  json: Object.assign({}, incoming, {
    row: row,
    plan: {
      can_promise: gaps.length === 0,
      gaps: gaps,
      max_lead_days: maxLead,
      window_start: windowStart ? fmt(windowStart) : '',
      window_end: windowEnd ? fmt(windowEnd) : '',
      line_plan: linePlan
    },
    _can_promise: gaps.length === 0,
    _gate_pass: !(cfg.hold_unruly === true && gaps.length > 0)
  })
}];

// A sku in the order has no rule in PRODUCT_RULES, and HOLD_UNRULED_ITEMS is true, so
// neither an honest shipping window nor an honest installation email can be produced.
// Held here rather than promised. Add the sku(s) to PRODUCT_RULES and re-run the order.
return $input.all().map((i) => ({
  json: Object.assign({}, i.json, {
    _outcome: 'held',
    _reason: 'no product rule for: ' + ((i.json.plan && i.json.plan.gaps) || []).join(', ')
  })
}));

// Composes the personalised order-confirmation email. Every number in it is traceable:
// the shipping window comes from plan-the-build (order date + product lead rules), never
// invented here. If the rules cannot support a window, the email says the window is
// coming rather than quoting one.
function esc(v) {
  return String(v == null ? '' : v).replace(/[<>&"]/g, function (c) {
    return { '<': '&lt;', '>': '&gt;', '&': '&amp;', '"': '&quot;' }[c];
  });
}
function prettyDate(d) {
  const months = ['January','February','March','April','May','June','July','August',
    'September','October','November','December'];
  const p = d.split('-');
  if (p.length !== 3) return d;
  const m = Number(p[1]) - 1;
  return (months[m] || p[1]) + ' ' + Number(p[2]) + ', ' + p[0];
}

const cfg = $('config').first().json;
const item = $input.first().json;
const order = item.order || {};
const plan = item.plan || {};

const lines = (plan.line_plan || []).map(function (lp) {
  const spec = (lp.spec ? ' — ' + esc(lp.spec) : '');
  return '<tr><td style="padding:6px 0">' + esc(lp.name) + spec + '</td>' +
         '<td style="padding:6px 0;text-align:right">x' + lp.qty + '</td></tr>';
}).join('');

const hasWindow = plan.can_promise && plan.window_start && plan.window_end;
const windowLine = hasWindow
  ? '<p>Your order is in the build queue. Based on current production lead times, it is ' +
    'due to ship <strong>between ' + prettyDate(plan.window_start) + ' and ' +
    prettyDate(plan.window_end) + '</strong>. We will email you the tracking the moment ' +
    'it leaves the workshop.</p>'
  : '<p>Your order is in the build queue. We will confirm your shipping window by email ' +
    'shortly, and send tracking the moment your piece leaves the workshop.</p>';

const subject = (cfg.confirm_subject || 'Your {company} order {order} — thank you')
  .replace('{company}', cfg.company_name)
  .replace('{order}', order.order_id || '');

const html =
  '<p>Hi ' + esc(order.customer_name || 'there') + ',</p>' +
  '<p>Thank you for your order with ' + esc(cfg.company_name) + '. Here is what we are ' +
  'making for you:</p>' +
  '<table>' + lines + '</table>' +
  windowLine +
  '<p>One of our makers will email you if anything about the spec needs a decision ' +
  'before we start.</p>' +
  '<p>— ' + esc(cfg.from_name || cfg.company_name) + '</p>';

const textLines = (plan.line_plan || []).map(function (lp) {
  return '  - ' + lp.qty + 'x ' + lp.name + (lp.spec ? ' (' + lp.spec + ')' : '');
}).join('\n');
const text =
  'Hi ' + (order.customer_name || 'there') + ',\n\n' +
  'Thank you for your order with ' + cfg.company_name + '. Here is what we are making ' +
  'for you:\n' + textLines + '\n' +
  (hasWindow
    ? 'It is due to ship between ' + prettyDate(plan.window_start) + ' and ' +
      prettyDate(plan.window_end) + '. We will email the tracking the moment it leaves ' +
      'the workshop.\n'
    : 'We will confirm your shipping window by email shortly.\n') +
  '\n— ' + (cfg.from_name || cfg.company_name);

return [{
  json: Object.assign({}, item, {
    customer_email: order.email || '',
    customer_subject: subject,
    customer_html: html,
    customer_text: text
  })
}];

// DEMO mode (no sheet configured): the whole run happened in memory. Nothing was written
// and nothing was sent — this node's output IS the result: the row that would land on the
// board and the email the customer would get. Open it to read both.
const plan = $('plan the build').first().json;
const mail = $('compose the confirmation').first().json;
return [{
  json: {
    _outcome: 'demo',
    _reason: 'BOARD_READY is false — row shown, not written; nothing emailed',
    order_key: plan.order_key,
    row: plan.row,
    email: {
      to: mail.customer_email,
      subject: mail.customer_subject,
      html: mail.customer_html,
      text: mail.customer_text
    }
  }
}];

// The row that lands on the board: heading columns only, nothing the sheet does not
// understand, no machinery fields.
const item = $input.first().json;
return [{ json: item.row }];

// PREVIEW mode (TEST_RUN true, TEST_EMAIL blank): the row is on the board but no email
// went out, so the board honestly still says 'New order' with no confirmation recorded.
// Open this node to read exactly what the customer would have received.
const mail = $('compose the confirmation').first().json;
return [{
  json: {
    _outcome: 'preview',
    _reason: 'preview mode — row written, confirmation email not sent',
    order_key: mail.order_key,
    email: {
      to: mail.customer_email,
      subject: mail.customer_subject,
      html: mail.customer_html,
      text: mail.customer_text
    }
  }
}];

// Builds the sheet-update object AFTER the confirmation email really went out (test or
// live mode): the confirmation timestamp and the Confirmed stage. Reads the plan node
// rather than the mail node's output, because a send node does not guarantee it passes
// the order through. Only heading columns are emitted; matching is on 'Order key'.
function nowText() {
  const d = new Date();
  const p = (n) => (n < 10 ? '0' : '') + n;
  return d.getFullYear() + '-' + p(d.getMonth() + 1) + '-' + p(d.getDate()) + ' ' +
         p(d.getHours()) + ':' + p(d.getMinutes());
}
const cfg = $('config').first().json;
const cols = cfg.columns || {};
const h = (k) => cols[k] || k;
const plan = $('plan the build').first().json;
const out = {};
out[h('order_key')] = plan.row[h('order_key')] != null ? plan.row[h('order_key')] : plan.order_key;
out[h('confirmation_sent')] = nowText();
out[h('stage')] = cfg.stage_confirmed || 'Confirmed';
return [{ json: out }];
